/* EQIL guard 1.2 (2026-10-07). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "820";
    var MODE = "";   // blank mode: the sim addresses options by position, so no inserted placeholder and no shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        var nv = 0, nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var v = String(values[i]).trim(), t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if (v !== "" && !isNaN(Number(v))) { nv++; }
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nv === texts.length || nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    /* 8. Text follows the language. The tables are the sim's own (vcI18n on the platform, .trans in the
       Open player). A string is replaced only when it is another language's value for a key the current
       language also has, and never when it is also a value of the current language itself. */
    var trCache = { lang: null, maps: null };
    function rawLang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        return String(l).toLowerCase().slice(0, 2);
    }
    function tables() {
        try { if (window.vcI18n && window.vcI18n._translations && typeof window.vcI18n._translations === "object") { var t = window.vcI18n._translations; for (var k in t) { if (t[k] && typeof t[k] === "object") { return t; } } } } catch (e) {}
        try { var f = sim(); if (f && f.trans && typeof f.trans === "object") { return f.trans; } } catch (e) {}
        return null;
    }
    function flat(o, pre, out, d) {
        if (!o || typeof o !== "object" || d > 4) { return out; }
        for (var k in o) {
            if (!Object.prototype.hasOwnProperty.call(o, k)) { continue; }
            var v = o[k];
            if (typeof v === "string") { out[pre + k] = v; }
            else if (v && typeof v === "object" && !Array.isArray(v)) { flat(v, pre + k + ".", out, d + 1); }
        }
        return out;
    }
    function squash(s) { return String(s).replace(/\s+/g, " ").replace(/^ | $/g, ""); }
    var decoder = null;
    function decode(s) {
        if (s.indexOf("&") < 0) { return s; }
        try { decoder = decoder || document.createElement("textarea"); decoder.innerHTML = s; return decoder.value; } catch (e) { return s; }
    }
    // a value with inline markup is several text nodes on the page: one piece per stretch between tags
    function pieces(v) {
        var p = String(v).split(/<[^>]*>/);
        for (var i = 0; i < p.length; i++) { p[i] = decode(p[i]); }
        return p;
    }
    var LETTER = /[A-Za-zÀ-ɏ]/;
    function quote(s) { return s.replace(/[.*+?^$()|[\]\\]/g, "\\$&"); }
    function template(a, b) {
        var parts = a.split(/\{(\w+)\}/), names = [], rx = "", lit = 0;
        for (var i = 0; i < parts.length; i++) {
            if (i % 2) { names.push(parts[i]); rx += (i === parts.length - 2 && parts[i + 1] === "") ? "([^\\s.,;:!?)]+)" : "(.+?)"; }
            else { rx += quote(parts[i]); lit += parts[i].replace(/\s/g, "").length; }
        }
        if (!names.length || lit < 10) { return null; }
        try { return { rx: new RegExp(rx), names: names, to: b }; } catch (e) { return null; }
    }
    function buildMaps(L) {
        var T = tables();
        if (!T || !T[L] || typeof T[L] !== "object") { return null; }
        var to = flat(T[L], "", {}, 0), own = {}, exact = {}, longs = [], tpls = [], k, j, P;
        for (k in to) {
            if (!Object.prototype.hasOwnProperty.call(to, k)) { continue; }
            P = pieces(to[k]);
            for (j = 0; j < P.length; j++) { own["~" + squash(P[j])] = 1; }
        }
        for (var src in T) {
            if (src === L || !Object.prototype.hasOwnProperty.call(T, src) || !T[src] || typeof T[src] !== "object") { continue; }
            var from = flat(T[src], "", {}, 0);
            for (k in from) {
                if (!Object.prototype.hasOwnProperty.call(from, k) || !Object.prototype.hasOwnProperty.call(to, k)) { continue; }
                var A = pieces(from[k]), B = pieces(to[k]);
                if (A.length !== B.length) { continue; }   // the translation restructured its markup: no safe pairing
                for (j = 0; j < A.length; j++) {
                    var a = squash(A[j]), b = squash(B[j]);
                    if (!a || !LETTER.test(a) || own["~" + a] || a === b) { continue; }
                    if (a.indexOf("{") >= 0) { var tp = template(a, b); if (tp) { tpls.push(tp); } continue; }
                    if (!Object.prototype.hasOwnProperty.call(exact, "~" + a)) { exact["~" + a] = b; }
                    if (a.length >= 16 && a.indexOf(" ") > 0) { longs.push([a, b]); }
                }
            }
        }
        longs.sort(function (x, y) { return y[0].length - x[0].length; });
        return { exact: exact, longs: longs, tpls: tpls };
    }
    function fill(tp, m) {
        return String(tp.to).replace(/\{(\w+)\}/g, function (all, n) { var i = tp.names.indexOf(n); return i >= 0 ? m[i + 1] : all; });
    }
    function retranslate() {
        var L = rawLang();
        if (trCache.lang !== L || !trCache.maps) { trCache.lang = L; trCache.maps = buildMaps(L); }
        var M = trCache.maps;
        if (!M || !document.body || !document.createTreeWalker) { return; }
        var w = document.createTreeWalker(document.body, 4, null, false), n, edits = [];
        while ((n = w.nextNode())) {
            var p = n.parentNode, tag = p ? p.nodeName : "";
            if (tag === "SCRIPT" || tag === "STYLE" || tag === "TEXTAREA") { continue; }
            var t = n.nodeValue;
            if (!t || !/\S/.test(t)) { continue; }
            // a node already checked in this language and not rewritten since costs nothing (live sliders
            // re-render often, and this runs after every DOM change)
            if (n.__eqilT === t && n.__eqilL === L) { continue; }
            n.__eqilT = t; n.__eqilL = L;
            var cur = squash(t), out = null, i;
            if (Object.prototype.hasOwnProperty.call(M.exact, "~" + cur)) { out = M.exact["~" + cur]; }
            else {
                var s = cur;
                for (i = 0; i < M.longs.length; i++) { if (s.indexOf(M.longs[i][0]) >= 0) { s = s.split(M.longs[i][0]).join(M.longs[i][1]); } }
                for (i = 0; i < M.tpls.length; i++) { var m = s.match(M.tpls[i].rx); if (m) { s = s.replace(m[0], fill(M.tpls[i], m)); } }
                if (s !== cur) { out = s; }
            }
