                else if (peer === 'horizontal_saas') { dInt += 5; dBook += 3; notes.push(this._t('note_r1_peer_saas')); }
                else if (peer === 'data_infra')  { dInt += 3; dBook += 8;  notes.push(this._t('note_r1_peer_datainfra')); }
                else if (peer === 'vertical')    { dInt += 2; dBook -= 5;  notes.push(this._t('note_r1_peer_vertical')); }

                // Valuation recompute from peer
                var ev = mult * this.ARR;           // EV in $M
                var equityFromEv = ev - this.NET_DEBT; // EV + Cash - Debt; here Net Debt = +11
                // Midpoint price comparative: just map EV/ARR through to implied equity value
                // We keep a simplified $M equity value (valuation display)
                ds.impliedValuation = Math.round(ev + (84 - 95)); // EV - net debt to get equity

                // Price range
                var pr = d.priceRange || 'hold';
                ds.priceRange = pr;
                if (pr === 'tighten') { dInt += 2; notes.push(this._t('note_r1_range_tighten')); }
                else if (pr === 'widen') { dBook -= 3; notes.push(this._t('note_r1_range_widen')); }

                // Secondary tranche
                var sec = d.secondary || 'primary_only';
                if (sec === 'primary_only') { dBook += 5; notes.push(this._t('note_r1_sec_primary')); }
                else { dBook -= 3; notes.push(this._t('note_r1_sec_secondary')); }

                // Gross spread
                var spr = parseFloat(d.spreadPct) || 6.5;
                ds.spreadPct = spr;
                if (spr === 7.0)        { dBank += 5; dSynd += 10; notes.push(this._t('note_r1_spread_70')); }
                else if (spr === 6.5)   { dSynd += 0; notes.push(this._t('note_r1_spread_65')); }
                else if (spr === 6.25)  { dBank -= 5; dSynd -= 10; notes.push(this._t('note_r1_spread_625')); }

            } else if (round === 2) {
                // SEC inquiry disclosure
                var inq = d.inquiryDisclosure || 'limited';
                ds.r2InquiryChoice = inq;
                if (inq === 'full')        { dInt += 20; dReg += 10; notes.push(this._t('note_r2_inquiry_full')); }
                else if (inq === 'limited'){ dInt -= 5;               notes.push(this._t('note_r2_inquiry_limited')); }
                else if (inq === 'none')   { dInt -= 30; dReg -= 30;  notes.push(this._t('note_r2_inquiry_none')); }

                // Meme-stock RF
                if (d.memeRf === 'include') { dInt += 2; notes.push(this._t('note_r2_meme_include')); }

                // MD&A prominence
                var md = d.mdaProminence || 'balanced';
                if (md === 'non_gaap_lead') { dInt -= 5; dBook += 3; notes.push(this._t('note_r2_mda_nongaap')); }
                else if (md === 'balanced') { dInt += 5;             notes.push(this._t('note_r2_mda_balanced')); }
                else if (md === 'gaap_first'){ dBook -= 5;           notes.push(this._t('note_r2_mda_gaapfirst')); }

                // Governance package
                var govHits = 0;
                if (d.govDualClass) { dGov -= 15; govHits += 1; }
                if (d.govStaggered) { dGov -= 10; govHits += 1; }
                if (d.govForum)     { dGov += 5; }
                if (govHits >= 2) notes.push(this._t('note_r2_gov_2plus'));
                else if (govHits === 1) notes.push(this._t('note_r2_gov_1'));

                // 10b5-1
                if (d.rule10b51 === 'pre_announce') { dInt += 3; dBank += 3; notes.push(this._t('note_r2_10b51_pre')); }
                else { dInt -= 2; }

            } else if (round === 3) {
                // Price talk
                var pt = d.priceTalk || 'hold';
                if (pt === 'hold')            { dInt += 5; dBook += 3; notes.push(this._t('note_r3_talk_hold')); }
                else if (pt === 'bump_20_22') { dBook += 2; notes.push(this._t('note_r3_talk_bump2022')); }
                else if (pt === 'bump_21_23') { dInt -= 5; dBook -= 8; notes.push(this._t('note_r3_talk_bump2123')); }

                // Upsize
                var up = d.upsize || 22;
                ds.sharesPrimary = up;
                if (up === 22)      { dBook += 3; notes.push(this._t('note_r3_size_22')); }
                else if (up === 25) { dBook += 0; notes.push(this._t('note_r3_size_25')); }
                else if (up === 28) { dBook -= 8; dBank -= 3; notes.push(this._t('note_r3_size_28')); }

                // Timeline
                var tl = d.timeline || 'hold';
                if (tl === 'accelerate') { dBook -= 2; notes.push(this._t('note_r3_timeline_accel')); }
                else if (tl === 'extend'){ dBook -= 3; notes.push(this._t('note_r3_timeline_extend')); }

                // Allocation signaling
                if (d.signaling === 'tell') { dBook += 5; dBank += 3; notes.push(this._t('note_r3_signal_tell')); }

            } else if (round === 4) {
                // SEC inquiry response (coherence with R2)
                var sr = d.secResponse || 'update_rf';
                var r2 = ds.r2InquiryChoice || 'limited';

                if (sr === 'update_rf') {
                    if (r2 === 'none')   { dInt -= 5;  dReg -= 10; notes.push(this._t('note_r4_sr_updaternone')); }
                    else                 { dInt += 10; dReg += 10; notes.push(this._t('note_r4_sr_updaterelse')); }
                } else if (sr === 'position_letter') {
                    dInt -= 15; dReg -= 20; notes.push(this._t('note_r4_sr_positionletter'));
                } else if (sr === 'delay') {
                    dInt -= 10; dReg -= 15; notes.push(this._t('note_r4_sr_delay'));
                }

                // ASC 606 position
                var ac = d.ascPosition || 'restate';
                if (ac === 'defend')       { dInt -= 20; dReg -= 25; notes.push(this._t('note_r4_asc_defend')); }
                else if (ac === 'prospective') { dInt -= 10; dReg -= 10; notes.push(this._t('note_r4_asc_prospective')); }
                else if (ac === 'restate') { dInt += 15; dReg += 5; ds.restated = true; notes.push(this._t('note_r4_asc_restate')); }

                // Customer concentration
                if (d.concentration === 'named') { dInt += 5; dBank -= 2; notes.push(this._t('note_r4_conc_named')); }
                else { dInt += 2; notes.push(this._t('note_r4_conc_unnamed')); }

            } else if (round === 5) {
                // PRICING NIGHT
                var alloc = d.allocation || 'lo_heavy';
                var shoe  = d.greenShoe  || 'naked_short';
                var day1  = d.day1Posture || 'stabilize';
                var priceChoice = d.finalPrice || '22';

                if (priceChoice === 'pull') {
                    ds.dealPulled = true;
                    ds.finalPrice = 0;
                    ds.netProceedsM = 0;
                    ds.day1PopPct = 0;
                    ds.day1Close  = 0;
                    dInt += 5; dBank -= 15;
                    notes.push(this._t('note_r5_pull'));
                } else {
                    var p = parseFloat(priceChoice);
                    ds.finalPrice = p;

                    var shares = ds.sharesPrimary || 22;
                    var gross  = p * shares;
                    var net    = gross * (1 - (ds.spreadPct / 100));
                    ds.netProceedsM = Math.round(net * 100) / 100;

                    // Base Day-1 pop by price vs. demand
                    var basePop;
                    if (p <= 20)      basePop = 18;
                    else if (p === 22) basePop = 16;
                    else if (p === 23) basePop = 10;
                    else if (p === 24) basePop = 6;
                    else               basePop = -2; // $25 break-issue risk

                    // Allocation adjustment
                    if (alloc === 'lo_heavy')      basePop += 4;
                    else if (alloc === 'balanced') basePop += 0;
                    else if (alloc === 'hf_concession') basePop -= 8;

                    // Book-quality and integrity adjustments
                    if (ds.bookQuality > 70) basePop += 3;
                    if (ds.bookQuality < 30) basePop -= 4;
                    if (ds.disclosureIntegrity < 50) basePop -= 5;

                    // Day-1 posture / shoe
                    if (day1 === 'stabilize')     basePop += 2;
                    else if (day1 === 'no_bid')   basePop -= 3;
                    else if (day1 === 'penalty')  basePop += 1;

                    if (shoe === 'naked_short')   basePop += 1;
                    else if (shoe === 'partial')  basePop += 0;
                    else if (shoe === 'exercise_full') basePop -= 2;

                    // Random shock ±2
                    var shock = (Math.random() * 4) - 2;
                    basePop += shock;

                    ds.day1PopPct = Math.round(basePop * 10) / 10;
                    ds.day1Close  = Math.round(p * (1 + basePop / 100) * 100) / 100;

                    // Allocation quality score component
                    if (alloc === 'lo_heavy')          { dBank += 10; dSynd += 5; notes.push(this._t('note_r5_alloc_lo')); }
                    else if (alloc === 'balanced')     { dBank += 3;  notes.push(this._t('note_r5_alloc_balanced')); }
                    else if (alloc === 'hf_concession'){ dBank -= 10; notes.push(this._t('note_r5_alloc_hf')); }

                    if (shoe === 'naked_short')      notes.push(this._t('note_r5_shoe_naked'));
                    else if (shoe === 'partial')     notes.push(this._t('note_r5_shoe_partial'));
                    else if (shoe === 'exercise_full') notes.push(this._t('note_r5_shoe_full'));

                    if (day1 === 'stabilize')        notes.push(this._t('note_r5_day1_stabilize'));
                    else if (day1 === 'penalty')     notes.push(this._t('note_r5_day1_penalty'));
                    else if (day1 === 'no_bid')      notes.push(this._t('note_r5_day1_nobid'));

                    if (basePop < 0)      { dBank -= 10; notes.push(this._t('note_r5_pop_broke')); }
                    else if (basePop > 35){ dBank -= 5;  notes.push(this._t('note_r5_pop_high')); }
                    else if (basePop >= 10 && basePop <= 20) { dBank += 5; notes.push(this._t('note_r5_pop_clean')); }
                }
            }

            // Apply deltas (with clamping)
            ds.disclosureIntegrity = Math.max(0, Math.min(100, ds.disclosureIntegrity + dInt));
            ds.bookQuality         = Math.max(0, Math.min(100, ds.bookQuality + dBook));
            ds.bankRelationship    = Math.max(0, Math.min(100, ds.bankRelationship + dBank));
            ds.governanceScore     = Math.max(0, Math.min(100, ds.governanceScore + dGov));
            ds.regulatoryScore     = Math.max(0, Math.min(100, ds.regulatoryScore + dReg));
            ds.syndicateEconomics  = Math.max(0, Math.min(100, ds.syndicateEconomics + dSynd));

            // Composite score (only meaningful after R5, but computed each round for chart)
            var proceedsScore;
            if (ds.dealPulled) proceedsScore = 0;
            else if (ds.netProceedsM > 0) proceedsScore = Math.min(100, (ds.netProceedsM / 500) * 100);
            else proceedsScore = 50; // pre-pricing placeholder

            var day1Score;
            if (ds.dealPulled) day1Score = 20;
            else if (ds.finalPrice === 0) day1Score = 50;
            else if (ds.day1PopPct < 0) day1Score = 30;
            else if (ds.day1PopPct > 35) day1Score = 60;
            else if (ds.day1PopPct >= 10 && ds.day1PopPct <= 20) day1Score = 100;
            else if (ds.day1PopPct >= 5 && ds.day1PopPct < 10) day1Score = 85;
            else if (ds.day1PopPct > 20 && ds.day1PopPct <= 35) day1Score = 80;
            else day1Score = 70;

            var allocScore;
            var allocChoice = (d && d.allocation) || 'lo_heavy';
            if (ds.dealPulled) allocScore = 30;
            else if (ds.finalPrice === 0) allocScore = 50;
            else if (allocChoice === 'lo_heavy') allocScore = 90;
            else if (allocChoice === 'balanced') allocScore = 70;
            else allocScore = 45;

            var composite =
                0.20 * proceedsScore +
                0.15 * day1Score +
                0.15 * allocScore +
                0.15 * ds.disclosureIntegrity +
                0.10 * ds.syndicateEconomics +
                0.10 * ds.bankRelationship +
                0.05 * ds.governanceScore +
                0.10 * ds.regulatoryScore;
            ds.dealQualityScore = Math.round(composite * 10) / 10;

            // Persist score into domainState for the grading/reporting layer
            // (results_utils.php reads domainState.performance.overallScore -> score).
            ds.score = ds.dealQualityScore;
            ds.performance = { overallScore: ds.dealQualityScore, grade: this._grade(ds.dealQualityScore) };

            // Push history for chart
            ds.integrityHistory.push(ds.disclosureIntegrity);
            ds.bookHistory.push(ds.bookQuality);
            ds.valuationHistory.push(ds.impliedValuation);
            ds.scoreHistory.push(ds.dealQualityScore);

            var results = {
                period: state.currentPeriod,
                roundName: this._roundName(round),
                dIntegrity:   Math.round(dInt * 10) / 10,
                dBookQuality: Math.round(dBook * 10) / 10,
                disclosureIntegrity: ds.disclosureIntegrity,
                bookQuality:         ds.bookQuality,
                impliedValuation:    ds.impliedValuation,
                dealQualityScore:    ds.dealQualityScore,
                finalPrice:          ds.finalPrice,
                day1PopPct:          ds.day1PopPct,
                netProceedsM:        ds.netProceedsM,
                dealPulled:          ds.dealPulled,
                score:               ds.dealQualityScore,
                overallScore:        ds.dealQualityScore,
                note:                notes.join(' ')
            };

            // Advance briefing to next round
            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })((state.currentPeriod || 1) + 1), 400);

            return results;
        }

        _t(key) {
            return (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t(key) : key;
        }

        _roundName(r) {
            var map = {
                1: 'roundname_1',
                2: 'roundname_2',
                3: 'roundname_3',
                4: 'roundname_4',
                5: 'roundname_5'
            };
            return map[r] ? this._t(map[r]) : (this._t('round_label') + ' ' + r);
        }

        _updateBriefing(state) {
            var round = Math.max(1, Math.min(5, state.currentPeriod || 1));

            // Show only the active round panel
            for (var i = 1; i <= 5; i++) {
                var panel = document.getElementById('roundPanel' + i);
                if (panel) {
                    panel.classList.toggle('active', i === round);
                }
            }

            var briefingTextEl = document.getElementById('briefingText');
            var briefingTitleEl = document.getElementById('briefingTitle');
            if (!briefingTextEl || !briefingTitleEl) return;

            var titleKeys = [
                '',
                'briefing_r1_title',
                'briefing_r2_title',
                'briefing_r3_title',
                'briefing_r4_title',
                'briefing_r5_title'
            ];

            var bodyKeys = [
                '',
                'body_r1',
                'body_r2',
                'body_r3',
                'body_r4',
                'body_r5'
            ];

            briefingTitleEl.textContent = titleKeys[round] ? this._t(titleKeys[round]) : '';
            briefingTextEl.innerHTML   = bodyKeys[round] ? this._t(bodyKeys[round]) : '';

            // Round 6+ (after R5 submitted): show debrief
            if ((state.currentPeriod || 1) > 5) {
                briefingTitleEl.textContent = this._t('debrief_title');
                briefingTextEl.innerHTML = this._t('debrief_body');
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay',  'currentPeriod');
            uiManager.bind('maxPeriods',  'maxPeriods');
            uiManager.bind('integrityDisplay',  'domainState.disclosureIntegrity',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('bookQualityDisplay', 'domainState.bookQuality',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('valuationDisplay',   'domainState.impliedValuation',
                (v) => '$' + (v / 1000).toFixed(2) + 'B');
            uiManager.bind('scoreDisplay',       'domainState.dealQualityScore',
                (v) => (v && v > 0) ? (Math.round(v * 10) / 10).toString() : '—');
        }

