                                backgroundColor: 'rgba(0,191,255,0.08)',
                                borderWidth: 2.5,
                                tension: 0.25,
                                fill: false,
                                pointRadius: 4,
                                pointHoverRadius: 6
                            },
                            {
                                label: this._t('kpi_score'),
