        getChartData(state) {
            var labels = state.domainState.integrityHistory.map((_, i) => 'R' + (i + 1));
            return {
                dealChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.integrityHistory },
                        { data: state.domainState.bookHistory },
                        { data: state.domainState.scoreHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (ds.disclosureIntegrity < 40) return window.mySimulation.t('hint_integrity_low');
            if (ds.bookQuality < 40)         return window.mySimulation.t('hint_book_low');
            if (ds.dealPulled)               return window.mySimulation.t('hint_deal_pulled');
            if (results.day1PopPct && results.day1PopPct < 0) return window.mySimulation.t('hint_broke_issue');
            if (results.day1PopPct && results.day1PopPct > 35) return window.mySimulation.t('hint_money_left');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName',            label: 'Round',          i18nKey: 'col_round' },
                { key: 'results.disclosureIntegrity',  label: 'Integrity',      i18nKey: 'col_integrity',  formatter: (v) => Math.round(v) },
                { key: 'results.bookQuality',          label: 'Book Quality',   i18nKey: 'col_book',       formatter: (v) => Math.round(v) },
                { key: 'results.impliedValuation',     label: 'Valuation',      i18nKey: 'col_valuation',  formatter: (v) => '$' + (v / 1000).toFixed(2) + 'B' },
                { key: 'results.dealQualityScore',     label: 'DQ Score',       i18nKey: 'col_score',      formatter: (v) => (Math.round(v * 10) / 10).toString() },
                { key: 'results.note',                 label: 'Commentary',     i18nKey: 'col_note' }
            ];
        }

        _grade(score) {
            // Same thresholds as tier_* in getPerformanceSummary, translated for display.
            if (score >= 75) return this._t('tier_excellent');
            if (score >= 60) return this._t('tier_good');
            if (score >= 45) return this._t('tier_average');
            return this._t('tier_beginner');
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = (last && last.results) || {};
            var ds = (last && last.domainState) || {};

            var score = r.dealQualityScore || ds.dealQualityScore || 0;
            var t = function(k) { return window.mySimulation.t(k); };
            var perfKey = 'tier_beginner';
            if (score >= 75) perfKey = 'tier_excellent';
            else if (score >= 60) perfKey = 'tier_good';
            else if (score >= 45) perfKey = 'tier_average';
            var performance = t(perfKey);

            var insights = [];
            if (ds.dealPulled) {
                insights.push(t('ins_pulled'));
            } else {
                if (r.day1PopPct >= 10 && r.day1PopPct <= 20) {
                    insights.push(t('ins_day1_clean'));
                } else if (r.day1PopPct < 0) {
                    insights.push(t('ins_day1_broke'));
                } else if (r.day1PopPct > 35) {
                    insights.push(t('ins_day1_high'));
                }
                if ((r.disclosureIntegrity || ds.disclosureIntegrity || 0) >= 85) {
                    insights.push(t('ins_integ_high'));
                } else if ((r.disclosureIntegrity || ds.disclosureIntegrity || 0) < 50) {
                    insights.push(t('ins_integ_low'));
                }
            }

            return {
                totalScore: score,
                overallScore: score,
                totalPeriods: history.length,
                performance: performance,
                finalPrice: r.finalPrice || ds.finalPrice,
                day1PopPct: r.day1PopPct || ds.day1PopPct,
                netProceedsM: r.netProceedsM || ds.netProceedsM,
                insights: insights
            };
        }

        getPresets() { return null; }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : ((typeof summary.totalScore === 'number') ? summary.totalScore : 0);
            var perfL = summary.performance || '';
            var color = score >= 75 ? '#2a9d8f' : (score >= 60 ? '#4c9be8' : (score >= 45 ? '#e9c46a' : '#e63946'));
            var kpis = [
                [t('comp_price'), (summary.finalPrice != null && summary.finalPrice !== 0) ? ('$' + summary.finalPrice) : '-'],
                [t('comp_day1'), (summary.day1PopPct != null) ? (summary.day1PopPct + '%') : '-'],
                [t('comp_proceeds'), (summary.netProceedsM != null) ? ('$' + Math.round(summary.netProceedsM) + 'M') : '-']
            ];
            var kpiRow = kpis.map(function(k) { return '<span style="display:inline-block;margin:4px 10px;"><strong>' + k[1] + '</strong> ' + k[0] + '</span>'; }).join('');
            var ins = summary.insights || [];
            var items = ins.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var insBlock = items ? ('<ul style="text-align:left;margin:12px auto 0;display:inline-block;">' + items + '</ul>') : '';
            return '<div class="completion-message text-center p-4">' +
                '<h4 style="margin-bottom:8px;">' + t('comp_heading') + '</h4>' +
                '<div style="font-size:2.6rem;font-weight:800;color:' + color + ';">' + (Math.round(score * 10) / 10) + '/100</div>' +
                '<p class="lead" style="margin:2px 0;">' + t('comp_score_label') + '</p>' +
                '<p style="font-weight:700;color:' + color + ';">' + perfL + '</p>' +
                '<p class="text-muted" style="margin:8px 0;">' + kpiRow + '</p>' +
                insBlock +
                '<hr class="my-3"><p class="text-muted">' + t('comp_thanks') + '</p></div>';
        }

