            return {
                en: {
                    title:                `The S-1 Filing: Prismview Analytics IPO`,
                    subtitle:             `NASDAQ: PRSM | Bookrunners: Morgan Stanley / Goldman Sachs / JPMorgan`,
                    round_label:          `Round`,
                    kpi_integrity:        `Disclosure Integrity`,
                    kpi_book:             `Book Quality`,
                    kpi_valuation:        `Implied Valuation`,
                    kpi_score:            `Deal Quality Score`,
                    decisions_heading:    `Deal Decisions`,
                    submit_btn:           `Submit Round`,
                    undo_btn:             `Undo Last Round`,
